_ES_USED = set()


def localize_es(text):
    for en, es in ES_MAP:
        if en in text:
            _ES_USED.add(en)
            text = text.replace(en, es)
    return re.sub(r'data-ldv-cta="', 'data-ldv-cta="es_', text)


def report_es_unused():
    unused = [en[:70] for en, _ in ES_MAP if en not in _ES_USED]
    print("ES: пар карты", len(ES_MAP), "| не сработало", len(unused), unused if unused else "")
